package com.mitraa.hackathon.team;
import com.mitraa.hackathon.registration.Registration; import jakarta.persistence.*; import java.time.Instant; import java.util.ArrayList; import java.util.List;
@Entity @Table(name="teams")
public class Team { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @OneToOne(optional=false,fetch=FetchType.LAZY) @JoinColumn(name="registration_id",unique=true) private Registration registration; @Column(nullable=false,length=100) private String name; @Column(nullable=false,unique=true,length=24) private String code; @OneToMany(mappedBy="team",cascade=CascadeType.ALL,orphanRemoval=true) private List<TeamMember> members=new ArrayList<>(); @Column(nullable=false,updatable=false) private Instant createdAt=Instant.now(); public Long getId(){return id;} public Registration getRegistration(){return registration;} public void setRegistration(Registration v){registration=v;} public String getName(){return name;} public void setName(String v){name=v;} public String getCode(){return code;} public void setCode(String v){code=v;} public List<TeamMember> getMembers(){return members;} public Instant getCreatedAt(){return createdAt;} public void addMember(TeamMember m){members.add(m);m.setTeam(this);} }
